<script>const products=@json($products->map(fn($p)=>['id'=>$p->id,'name'=>$p->name,'sku'=>$p->sku]));let row=0;function addRow(){const i=row++;const options=products.map(p=>`<option value="${p.id}">${p.name} — ${p.sku}</option>`).join('');document.getElementById('items').insertAdjacentHTML('beforeend',`<tr class="border-t"><td class="p-3"><select name="items[${i}][product_id]" required class="w-full rounded border p-2">${options}</select></td><td class="p-3"><input name="items[${i}][quantity]" type="number" step="0.001" min="0.001" value="1" required class="w-24 rounded border p-2"></td><td class="p-3"><input name="items[${i}][unit_cost]" type="number" step="0.01" min="0" value="0" required class="w-32 rounded border p-2"></td><td class="p-3"><input name="items[${i}][discount]" type="number" step="0.01" min="0" value="0" class="w-28 rounded border p-2"></td><td class="p-3"><input name="items[${i}][tax]" type="number" step="0.01" min="0" value="0" class="w-28 rounded border p-2"></td><td class="p-3"><button type="button" onclick="this.closest('tr').remove()" class="text-red-600">Hapus</button></td></tr>`)}addRow();</script></body></html>
